import os,json,struct,re
from volatility3.plugins.windows import windows
class Heapscan(windows.Windows):
 def _generator(self):
  out=[]
  for sn,dn,w,wn in self.list_windows(self.context,self.config_path,self.config['kernel']):
   if w.vol.offset != 0xbd5b448f45b0:continue
   sp=w.subPointer.dereference(); lay=self.context.layers[sp.vol.layer_name]; data=lay.read(sp.vol.offset,512,pad=True); base=sp.vol.offset & ~0xfffff
   seen=set()
   for off in range(0,len(data)-7,8):
    q=struct.unpack_from('<Q',data,off)[0]
    if not (0x1000<=q<0x100000) or q in seen:continue
    seen.add(q);addr=base+q
    try:b=lay.read(addr,1024,pad=True)
    except Exception as e:continue
    u=[]
    for m in re.finditer(rb'(?:[\x20-\x7e]\x00){3,}',b):u.append([m.start(),m.group().decode('utf-16le','ignore')])
    a=[]
    for m in re.finditer(rb'[\x20-\x7e]{4,}',b):a.append([m.start(),m.group().decode('ascii','ignore')])
    if u or a:out.append({'source_offset':off,'value':hex(q),'address':hex(addr),'utf16':u,'ascii':a,'hex':b.hex()})
  json.dump(out,open(os.environ['OUTJSON'],'w'),indent=2)
  yield from super()._generator()
PY
